-        @Override
-        public void addValue(int docID, float[] vectorValue) throws IOException {
-            docsWithField.add(docID);
-            floatVectors.add(vectorValue);
-            if (indexingDelegate != null) {
-                indexingDelegate.addValue(docID, vectorValue);
-            }
-        }
