-            }
-            return vectorList.get(curDoc);
-        }
-
-        @Override
-        public int docID() {
-            if (curDoc >= vectorList.size()) {
-                return NO_MORE_DOCS;
-            }
-            return curDoc;
-        }
-
-        @Override
-        public int nextDoc() throws IOException {
-            curDoc++;
-            return docID();
-        }
-
-        @Override
-        public int advance(int target) throws IOException {
-            curDoc = target;
-            return docID();
-        }
-    }
